function intersectLists(first, second) {
  const result = []
  let i = 0
  let j = 0
  while (i < first.length && j < second.length) {
    const lo = Math.max(first[i][0], second[j][0])
    const hi = Math.min(first[i][1], second[j][1])
    if (lo <= hi) result.push([lo, hi])
    if (first[i][1] < second[j][1]) i++
    else j++
  }
  return result
}

